import tailwindcss from '@tailwindcss/vite'

// Theme defaults; override with NUXT_PUBLIC_THEME_* (see ../.env.example).
// The real .env lives at the repo root; package.json scripts pass `--dotenv ../.env`
// (missing file is ignored, existing process env wins).
export default defineNuxtConfig({
  compatibilityDate: '2026-09-01',
  devtools: { enabled: false },
  modules: ['@nuxt/eslint'],
  css: ['~/assets/css/main.css'],
  devServer: { port: Number(process.env.WEB_PORT) || 9180 },
  vite: { plugins: [tailwindcss()] },
  runtimeConfig: {
    // Private (server-only): API base used during SSR. In Docker, `localhost` is the web container
    // itself, so compose sets NUXT_API_BASE_SERVER=http://api:9181. Empty falls back to public.apiBase.
    apiBaseServer: '',
    public: {
      // Browser-facing API base (NUXT_PUBLIC_API_BASE).
      apiBase: 'http://localhost:9181',
      theme: {
        lightPrimary: '#32a9e1',
        lightSecondary: '#1e40af',
        lightBackground: '#ffffff',
        darkPrimary: '#7dd3fc',
        darkSecondary: '#94a3b8',
        darkBackground: '#020617',
      },
    },
  },
})
<script setup lang="ts">
const { public: { theme } } = useRuntimeConfig()
const mode = useThemeMode()

useHead({
  htmlAttrs: {
    lang: 'en',
    'data-theme': computed(() => (mode.value === 'system' ? undefined : mode.value)),
  },
  title: 'SCMP Internal Operations AI Assistant',
  style: [{ id: 'theme-vars', innerHTML: buildThemeCss(theme) }],
})
</script>

<template>
  <NuxtLayout>
    <NuxtPage />
  </NuxtLayout>
</template>
export default defineNuxtRouteMiddleware(async (to) => {
  const { user, notice, checked, fetchMe } = useAuth()

  // First render (SSR) validates the httpOnly session cookie via /me; the result travels to the browser
  // in the payload, so hydration and later navigations do not repeat the call.
  if (!checked.value) await fetchMe()

  if (to.path === '/login') return user.value ? navigateTo('/') : undefined
  if (!user.value) {
    // An SSR redirect starts a new request, so carry the "expired" reason in a harmless query flag.
    return navigateTo(notice.value ? { path: '/login', query: { reason: 'expired' } } : '/login')
  }
})
<template>
  <div class="min-h-screen bg-background text-secondary">
    <!-- Top-left: the top-right corner belongs to the One Tap card. -->
    <div class="absolute left-4 top-4">
      <ThemeToggle />
    </div>
    <slot />
  </div>
</template>
<!-- Fixed-height shell: the header stays put and each page scrolls (or, for the chat, lays itself out) below it. -->
<template>
  <div class="flex h-dvh flex-col bg-background text-secondary">
    <AppHeader class="shrink-0" />
    <div class="min-h-0 flex-1 overflow-y-auto">
      <slot />
    </div>
  </div>
</template>
<script setup lang="ts">
useHead({ title: 'Home - SCMP Internal Operations AI Assistant' })

const { user } = useAuth()
const capabilities = computed(() => (user.value ? ROLE_CAPABILITIES[user.value.role] : null))
</script>

<!-- Employees get the chat; the chat API answers 403 for approvers, so they keep the capabilities panel. -->
<template>
  <main v-if="user?.role === 'employee'" class="h-full">
    <ChatWorkspace />
  </main>

  <main v-else-if="user && capabilities" class="mx-auto max-w-3xl space-y-6 px-4 py-8">
    <section>
      <h1 class="text-2xl font-bold">
        Signed in as {{ user.display_name }} ({{ roleLabel(user.role) }})
      </h1>
      <p class="mt-1 text-sm opacity-90">
        {{ user.email }}
      </p>
    </section>

    <MockWarning :title="MOCK_SESSION_REMINDER.title" :text="MOCK_SESSION_REMINDER.text" role="note" />

    <section class="rounded-2xl border border-secondary/30 p-5" aria-labelledby="capabilities-title">
      <div class="flex flex-wrap items-center gap-2">
        <h2 id="capabilities-title" class="text-lg font-semibold">
          What you can do
        </h2>
        <RoleBadge :role="user.role" />
      </div>
      <p class="mt-2 text-sm opacity-90">
        {{ capabilities.summary }}
      </p>
      <ul class="mt-4 space-y-2">
        <li
          v-for="item in capabilities.items"
          :key="item"
          class="flex flex-wrap items-center justify-between gap-2 rounded-lg border border-secondary/20 px-3 py-2"
        >
          <span>{{ item }}</span>
          <span class="rounded-full border border-secondary/40 px-2 py-0.5 text-xs font-medium">Coming in the next phase</span>
        </li>
      </ul>
    </section>
  </main>
</template>
<script setup lang="ts">
definePageMeta({ layout: 'auth' })
useHead({ title: 'Sign in - SCMP Internal Operations AI Assistant' })

const { notice, expiredNotice } = useAuth()
const route = useRoute()
const message = computed(() => notice.value ?? (route.query.reason === 'expired' ? expiredNotice : null))

// The mock One Tap prompt is shown on load (no click, no cooldown); closing it reveals the button below.
const cardOpen = ref(true)
const card = ref<{ focus: () => void } | null>(null)
const signInButton = ref<{ $el: HTMLElement } | null>(null)

async function openCard() {
  cardOpen.value = true
  await nextTick()
  card.value?.focus() // the user asked for it, so moving focus here is expected
}

async function closeCard(focusWasInside: boolean) {
  cardOpen.value = false
  if (!focusWasInside) return
  await nextTick()
  signInButton.value?.$el.focus() // do not leave keyboard users on <body>
}
// From 768px the fixed card sits beside the copy (360px + 16px gutters reserved via padding);
// 640-767px it overlays the page; under 640px it flows in at the top with 8px side margins.
</script>

<template>
  <div :class="cardOpen ? 'md:pr-[392px]' : ''">
    <main class="mx-auto flex min-h-screen max-w-xl flex-col justify-center gap-6 px-4 py-16">
      <GoogleOneTapCard v-if="cardOpen" ref="card" @close="closeCard" />

      <header>
        <p class="text-sm font-semibold uppercase tracking-wide">
          Internal operations demo
        </p>
        <h1 class="mt-2 text-3xl font-bold">
          SCMP Internal Operations AI Assistant
        </h1>
        <p class="mt-3 opacity-90">
          A proof-of-concept employee self-service assistant for Leave Applications and Staff Claims.
          It uses fictional data only.
        </p>
      </header>

      <MockWarning :title="MOCK_WARNING.title" :text="MOCK_WARNING.text" />

      <p
        v-if="message"
        role="status"
        class="rounded-lg border border-secondary/40 p-3 text-sm"
      >
        {{ message }}
      </p>

      <div v-if="cardOpen">
        <p class="text-sm opacity-90">
          Pick a fictional account in the Google sign-in prompt to continue.
        </p>
      </div>
      <div v-else>
        <GoogleSignInButton ref="signInButton" aria-controls="one-tap-card" aria-expanded="false" @click="openCard" />
        <p class="mt-3 text-sm opacity-90">
          Opens the sign-in prompt with a list of fictional accounts. No real Google account is used.
        </p>
      </div>
    </main>
  </div>
</template>
import type { NitroFetchOptions, NitroFetchRequest } from 'nitropack'

const EXPIRED_NOTICE = 'Your session has expired. Please sign in again.'

/**
 * Session state. The session JWT lives only in the API's httpOnly `scmp_session` cookie, which page scripts
 * cannot read; this composable never sees or stores it. Auth state is just the (non-secret) user object in
 * `useState`, which is safe to serialise into the SSR payload.
 *
 * Every browser call to the API is cross-origin (web :9180 -> API :9181), so it uses `credentials: 'include'`.
 * During SSR the incoming request's `cookie` header is forwarded to the API by hand.
 */
export function useAuth() {
  const nuxtApp = useNuxtApp()
  const config = useRuntimeConfig()
  // Read once, in a valid Nuxt context (empty object in the browser).
  const ssrCookie = useRequestHeaders(['cookie']).cookie

  const user = useState<AuthUser | null>('auth-user', () => null)
  const notice = useState<string | null>('auth-notice', () => null)
  /** True once the session has been validated (server render) or set by an explicit sign-in / sign-out. */
  const checked = useState<boolean>('auth-checked', () => false)

  function apiBase(): string {
    return resolveApiBase({
      isServer: import.meta.server,
      publicBase: config.public.apiBase,
      serverBase: import.meta.server ? config.apiBaseServer : undefined, // private key: never read in the browser
    })
  }

  // navigateTo needs the Nuxt context, which is lost after an `await` in event handlers.
  // Re-enter it only when it is really missing: a nested runWithContext during SSR would clear the
  // outer context and break later composable calls in the same middleware.
  function withContext<T>(fn: () => T): T {
    return tryUseNuxtApp() ? fn() : nuxtApp.runWithContext(fn) as T
  }

  /** Low-level API call: base URL, cookie credentials, CSRF header. No 401 handling (see useApi). */
  async function request<T>(path: string, options: NitroFetchOptions<NitroFetchRequest> = {}): Promise<T> {
    return await $fetch<T>(path, {
      ...options,
      baseURL: apiBase(),
      headers: apiRequestHeaders(
        options.method,
        options.headers as Record<string, string> | undefined,
        import.meta.server ? ssrCookie : undefined,
      ),
      ...(import.meta.client ? { credentials: 'include' as const } : {}),
    }) as T
  }

  function clearSession(message: string | null = null) {
    user.value = null
    notice.value = message
  }

  async function listMockUsers(): Promise<AuthUser[]> {
    return parseMockUsers(await request<unknown>('/api/auth/mock-users', { timeout: 8000 }))
  }

  /** Signs in as a seeded mock user (the API sets the httpOnly cookie), stores the user and redirects home. */
  async function login(email: string): Promise<AuthUser> {
    const data = await request<Partial<LoginResponse>>('/api/auth/mock-google/login', {
      method: 'POST',
      body: { email },
      timeout: 8000,
    })
    if (!isAuthUser(data.user)) throw new Error('Malformed login response')
    user.value = data.user
    notice.value = null
    checked.value = true
    await withContext(() => navigateTo('/'))
    return data.user
  }

  /**
   * Validates the session cookie with /api/auth/me (server: forwards the incoming cookie header).
   * A 401/403 clears the user; the "expired" notice is only set when a session actually existed.
   */
  async function fetchMe(): Promise<AuthUser | null> {
    if (import.meta.server && !ssrCookie) {
      user.value = null // no cookies at all: cannot be signed in, skip the API call
      checked.value = true
      return null
    }
    const hadSession = user.value !== null || hasSessionCookie(ssrCookie)
    try {
      const me = await request<unknown>('/api/auth/me', { timeout: 8000 })
      if (!isAuthUser(me)) throw new Error('Malformed /me response')
      user.value = me
      return me
    }
    catch (error) {
      const status = extractStatus(error)
      if (status === 401 || status === 403) clearSession(hadSession ? EXPIRED_NOTICE : null)
      else user.value = null
      return null
    }
    finally {
      checked.value = true
    }
  }

  /** Best-effort server logout (clears the cookie); the local session is always cleared. */
  async function logout() {
    try {
      await request('/api/auth/logout', { method: 'POST', timeout: 3000 })
    }
    catch { /* best effort */ }
    clearSession()
    checked.value = true
    await withContext(() => navigateTo('/login'))
  }

  return { user, notice, checked, apiBase, withContext, request, clearSession, listMockUsers, login, fetchMe, logout, expiredNotice: EXPIRED_NOTICE }
}
import type { NitroFetchOptions, NitroFetchRequest } from 'nitropack'

/**
 * `$fetch` wrapper for authenticated API calls: sends the httpOnly session cookie (`credentials: 'include'`,
 * or the forwarded cookie header during SSR), adds the CSRF header on unsafe methods, and signs the user out
 * (clearing state and redirecting to /login) when the API answers 401.
 */
export function useApi() {
  const { request, clearSession, withContext, expiredNotice } = useAuth()

  return async function api<T>(path: string, options: NitroFetchOptions<NitroFetchRequest> = {}): Promise<T> {
    try {
      return await request<T>(path, options)
    }
    catch (error) {
      if (extractStatus(error) === 401) {
        clearSession(expiredNotice)
        await withContext(() => navigateTo('/login'))
      }
      throw error
    }
  }
}
interface BlobEntry {
  refs: number
  objectUrl: string | null
  promise: Promise<string>
}

// Shared by every thumbnail of the same file (message bubble and card): one download, one object URL.
// Module-level on purpose; it is only touched from mounted components in the browser.
const cache = new Map<string, BlobEntry>()

/**
 * Loads attachment files as object URLs. Files are fetched with `useApi` (session cookie, CSRF header,
 * cross-origin credentials), never through a plain `<img src>`. Every `acquire` must be paired with a `release`;
 * the object URL is revoked when the last user releases it.
 */
export function useAttachmentBlobs() {
  const api = useApi()

  function acquire(path: string): Promise<string> {
    const existing = cache.get(path)
    if (existing) {
      existing.refs++
      return existing.promise
    }
    const entry: BlobEntry = {
      refs: 1,
      objectUrl: null,
      promise: Promise.resolve(''),
    }
    entry.promise = api<Blob>(path, { responseType: 'blob' }).then((blob) => {
      const url = URL.createObjectURL(blob)
      if (entry.refs <= 0) {
        URL.revokeObjectURL(url) // everyone left while it was loading
        cache.delete(path)
        return url
      }
      entry.objectUrl = url
      return url
    })
    entry.promise.catch(() => {
      // A failed download is not cached, so a later attempt can succeed.
      if (cache.get(path) === entry) cache.delete(path)
    })
    cache.set(path, entry)
    return entry.promise
  }

  function release(path: string) {
    const entry = cache.get(path)
    if (!entry) return
    entry.refs--
    if (entry.refs > 0) return
    if (entry.objectUrl) URL.revokeObjectURL(entry.objectUrl)
    cache.delete(path)
  }

  return { acquire, release }
}
/** Cookie-backed theme mode; readable on server and client, so SSR output matches hydration. */
export function useThemeMode() {
  const cookie = useCookie<string>('theme-mode', {
    default: () => 'system',
    sameSite: 'lax',
    maxAge: 60 * 60 * 24 * 365,
  })
  const mode = computed<ThemeMode>({
    get: () => (isThemeMode(cookie.value) ? cookie.value : 'system'),
    set: (value) => {
      cookie.value = value
    },
  })
  return mode
}
/** Types for the Phase 2 chat API (see docs/chat-api-contract.md). All data is fictional. */
/* Card payload types carry a "Data" suffix so they never shadow the Vue components of the same name. */

export type RequestType = 'leave' | 'claim'

export interface ConversationSummary {
  id: number
  /** First user message (max 60 chars); "New chat" while empty. */
  title: string
  status: 'active' | 'closed'
  /** Form currently being filled. */
  active_request_type: RequestType | null
  /** An open confirmation card is waiting. */
  has_pending_card: boolean
  created_at: string
  updated_at: string
}

export type TraceStepKey = 'understand' | 'merge' | 'validate' | 'decide' | 'submit' | 'status' | 'respond'

export interface TraceStep {
  step: TraceStepKey
  label: string
  detail: string
  ok: boolean
  duration_ms: number
}

export type CardState = 'open' | 'used' | 'superseded' | 'discarded'
export type CardAction = 'create' | 'update' | 'cancel' | 'retry'

/** A staged or sent file (Phase 2b). `url` is relative to the API base; fetch it with credentials. */
export interface AttachmentInfo {
  id: number
  filename: string
  content_type: string
  size_bytes: number
  url: string
  created_at: string
}

export interface CardField {
  key: string
  label: string
  value: string
  /** Only on updates: the previous value, shown as a struck-through diff. */
  old_value: string | null
  /** "document" when the value was read from an attachment. */
  source?: 'document' | null
}

export interface ConfirmationCardData {
  type: 'confirmation_card'
  card_id: string
  action: CardAction
  request_type: RequestType
  request_id: number | null
  title: string
  fields: CardField[]
  warnings: string[]
  state: CardState
  confirm_label: string
  /** Documents that will be linked to the request (Phase 2b). */
  attachments?: AttachmentInfo[]
}

export type RequestStatus = 'draft' | 'pending_approval' | 'submission_failed' | 'approved' | 'rejected' | 'cancelled'

export interface StatusRequest {
  request_type: RequestType
  id: number
  status: RequestStatus
  status_label: string
  summary: string
  submitted_at: string | null
  reviewed_at: string | null
  reviewer_note: string | null
  external_reference_id: string | null
}

export interface StatusCardData {
  type: 'status_card'
  requests: StatusRequest[]
  empty: boolean
}

export type ResultOutcome = 'submitted' | 'updated' | 'cancelled' | 'failed'

export interface ResultCardData {
  type: 'result_card'
  outcome: ResultOutcome
  request_type: RequestType
  request_id: number
  status: RequestStatus
  status_label: string
  message: string
  external_reference_id: string | null
}

export type MessageUi = ConfirmationCardData | StatusCardData | ResultCardData

export interface Message {
  id: number
  sender_type: 'user' | 'assistant' | 'system'
  /** Plain text: always render as text, never as HTML. */
  content: string
  created_at: string
  ui: MessageUi | null
  trace: TraceStep[] | null
  /** Files on a user message (Phase 2b); may be absent on older payloads. */
  attachments?: AttachmentInfo[]
}

export type WarningCode = 'llm_unavailable' | 'llm_invalid_output' | 'submission_failed' | 'stale_card'

export interface TurnResponse {
  conversation: ConversationSummary
  user_message: Message | null
  assistant_messages: Message[]
  warning_code: WarningCode | null
}

export interface ConversationDetail {
  conversation: ConversationSummary
  messages: Message[]
}

export interface ConversationList {
  items: ConversationSummary[]
}
/** Pure, framework-free auth helpers (unit-tested offline in tests/auth.test.ts). */

export type Role = 'employee' | 'hr_approver' | 'finance_approver'

export interface AuthUser {
  id: number
  email: string
  display_name: string
  role: Role
}

/** Body of POST /api/auth/mock-google/login. The session JWT is NOT in the body: it travels only in the httpOnly cookie. */
export interface LoginResponse {
  expires_in: number
  user: AuthUser
}

/** Name of the httpOnly session cookie the API sets (the frontend can never read its value). */
export const SESSION_COOKIE_NAME = 'scmp_session'

/** Sent on every unsafe request; the API rejects state-changing calls without it (CSRF check). */
export const CSRF_HEADER = { name: 'X-Requested-With', value: 'XMLHttpRequest' } as const

/** Canonical display order (matches the order the API returns mock users in). */
export const ROLES: readonly Role[] = ['employee', 'hr_approver', 'finance_approver']

export const ROLE_LABELS: Readonly<Record<Role, string>> = {
  employee: 'Employee',
  hr_approver: 'HR Approver',
  finance_approver: 'Finance Approver',
}

export const ROLE_GROUP_LABELS: Readonly<Record<Role, string>> = {
  employee: 'Employees',
  hr_approver: 'HR approvers',
  finance_approver: 'Finance approvers',
}

/** Single source of truth for the mock-SSO warning; reused by the login page and the One Tap card. */
export const MOCK_WARNING = {
  title: 'Mock sign-in: demonstration only',
  text: 'This is a demonstration-only mock sign-in. It is not connected to Google. '
    + 'Choosing an account signs you in immediately as that fictional user, with no password.',
} as const

export const MOCK_SESSION_REMINDER = {
  title: 'Mock session',
  text: 'You are signed in through the demonstration-only mock Google sign-in as a fictional user. '
    + 'No real Google account, password or SCMP data is involved.',
} as const

export interface RoleCapabilities {
  summary: string
  items: readonly string[]
}

/** Product scope from AGENTS.md; every item ships in a later phase. */
export const ROLE_CAPABILITIES: Readonly<Record<Role, RoleCapabilities>> = {
  employee: {
    summary: 'Submit your own requests and follow their status.',
    items: [
      'Create a Leave Application',
      'Create a Staff Claim',
      'View your own requests only',
    ],
  },
  hr_approver: {
    summary: 'Review Leave requests. Staff Claims are out of scope for this role.',
    items: [
      'List Leave requests',
      'View Leave request details',
      'Approve or reject Leave requests',
    ],
  },
  finance_approver: {
    summary: 'Review Staff Claims. Leave requests are out of scope for this role.',
    items: [
      'List Staff Claims',
      'View Staff Claim details',
      'Approve or reject Staff Claims',
    ],
  },
}

export function isRole(value: unknown): value is Role {
  return typeof value === 'string' && (ROLES as readonly string[]).includes(value)
}

export function roleLabel(role: unknown): string {
  return isRole(role) ? ROLE_LABELS[role] : 'Unknown role'
}

export function isAuthUser(value: unknown): value is AuthUser {
  if (typeof value !== 'object' || value === null) return false
  const v = value as Record<string, unknown>
  return typeof v.id === 'number'
    && typeof v.email === 'string' && v.email.length > 0
    && typeof v.display_name === 'string'
    && isRole(v.role)
}

/** Keeps only well-formed users from an untrusted API payload. */
export function parseMockUsers(payload: unknown): AuthUser[] {
  return Array.isArray(payload) ? payload.filter(isAuthUser) : []
}

export interface RoleGroup {
  role: Role
  label: string
  users: AuthUser[]
}

/** Groups users by role in canonical order, omitting empty groups. */
export function groupUsersByRole(users: readonly AuthUser[]): RoleGroup[] {
  return ROLES
    .map(role => ({ role, label: ROLE_GROUP_LABELS[role], users: users.filter(u => u.role === role) }))
    .filter(group => group.users.length > 0)
}

/** Up to two initials (first + last word), falling back to the e-mail, then "?". */
export function getInitials(displayName: string | null | undefined, email?: string | null): string {
  const words = (displayName ?? '').trim().split(/\s+/).filter(Boolean)
  const letters = (word: string) => Array.from(word)[0] ?? ''
  if (words.length >= 2) return (letters(words[0]!) + letters(words[words.length - 1]!)).toUpperCase()
  if (words.length === 1) return letters(words[0]!).toUpperCase()
  const fromEmail = letters((email ?? '').trim())
  return fromEmail ? fromEmail.toUpperCase() : '?'
}

const AVATAR_COLOURS = ['#1967d2', '#188038', '#a50e0e', '#8430ce', '#0b6e7f', '#b06000'] as const

/** Deterministic avatar background; every colour gives >= 4.5:1 with white initials. */
export function avatarColour(seed: string): string {
  let hash = 0
  for (const ch of seed) hash = (hash * 31 + ch.charCodeAt(0)) >>> 0
  return AVATAR_COLOURS[hash % AVATAR_COLOURS.length]!
}

/** First word of the display name (for "Continue as ..."), falling back to the e-mail local part, then "account". */
export function firstName(displayName: string | null | undefined, email?: string | null): string {
  const word = (displayName ?? '').trim().split(/\s+/).find(Boolean)
  if (word) return word
  const local = (email ?? '').trim().split('@')[0]
  return local || 'account'
}

export function isUnsafeMethod(method: string | null | undefined): boolean {
  return !['GET', 'HEAD', 'OPTIONS'].includes((method ?? 'GET').toUpperCase())
}

/** True when a raw `Cookie` request header carries the session cookie (name only; the value is never inspected). */
export function hasSessionCookie(cookieHeader: string | null | undefined): boolean {
  return (cookieHeader ?? '').split(';').some(part => part.trim().startsWith(`${SESSION_COOKIE_NAME}=`))
}

/**
 * Headers for an API call: adds the CSRF header for unsafe methods and, during SSR only (the caller passes
 * `forwardCookie`), forwards the incoming request's `Cookie` header. Never adds an Authorization header.
 */
export function apiRequestHeaders(
  method: string | null | undefined,
  extra: Record<string, string> = {},
  forwardCookie?: string | null,
): Record<string, string> {
  const headers: Record<string, string> = { ...extra }
  if (isUnsafeMethod(method)) headers[CSRF_HEADER.name] = CSRF_HEADER.value
  if (forwardCookie) headers.cookie = forwardCookie
  return headers
}

/** Extracts an HTTP status from an ofetch/FetchError-like value; undefined for network errors. */
export function extractStatus(error: unknown): number | undefined {
  if (typeof error !== 'object' || error === null) return undefined
  const e = error as { status?: unknown, statusCode?: unknown, response?: { status?: unknown } }
  for (const candidate of [e.statusCode, e.status, e.response?.status]) {
    if (typeof candidate === 'number' && candidate >= 100) return candidate
  }
  return undefined
}

export type AuthAction = 'list-users' | 'login'

/** User-facing message for an auth API failure (never echoes server text or tokens). */
export function authErrorMessage(status: number | undefined, action: AuthAction): string {
  if (status === undefined) return 'Cannot reach the API. Check that the backend is running and try again.'
  if (status === 404) return 'Mock sign-in is disabled on this server.'
  if (action === 'login') {
    if (status === 401) return 'That mock account was not recognised. Please choose another.'
    if (status === 403) return 'That account is inactive and cannot sign in.'
  }
  if (status >= 500) return 'The server had a problem. Please try again in a moment.'
  return 'Something went wrong. Please try again.'
}

/** Picks the API base URL: private container-network URL during SSR, public URL in the browser. */
export function resolveApiBase(opts: { isServer: boolean, publicBase: string, serverBase?: string | null }): string {
  const chosen = opts.isServer && opts.serverBase ? opts.serverBase : opts.publicBase
  return chosen.replace(/\/+$/, '')
}

/** Pure, framework-free chat helpers (unit-tested offline in tests/chat.test.ts). */
import type {
  AttachmentInfo,
  CardAction,
  CardField,
  CardState,
  ConfirmationCardData,
  ConversationSummary,
  Message,
  RequestStatus,
  ResultOutcome,
  TurnResponse,
  WarningCode,
} from '../types/chat'

export const MAX_MESSAGE_LENGTH = 1000

/** Suggestion chips of the empty state; picking one sends it as a message. */
export const CHAT_SUGGESTIONS: readonly string[] = [
  'I need annual leave next Monday and Tuesday',
  'Half day sick leave tomorrow afternoon',
  'Claim HKD 180 for a taxi yesterday',
  'What is the status of my requests?',
]

/* ---- Status badges: colour is never the only cue (each tone has an icon and a text label) ---- */

export type Tone = 'amber' | 'green' | 'red' | 'grey'
export type IconName = 'clock' | 'check' | 'x' | 'alert' | 'ban' | 'pencil'

export interface StatusMeta {
  label: string
  tone: Tone
  icon: IconName
}

const STATUS_META: Readonly<Record<RequestStatus, StatusMeta>> = {
  draft: { label: 'Draft', tone: 'grey', icon: 'pencil' },
  pending_approval: { label: 'Pending approval', tone: 'amber', icon: 'clock' },
  submission_failed: { label: 'Submission failed', tone: 'red', icon: 'alert' },
  approved: { label: 'Approved', tone: 'green', icon: 'check' },
  rejected: { label: 'Rejected', tone: 'red', icon: 'x' },
  cancelled: { label: 'Cancelled', tone: 'grey', icon: 'ban' },
}

/** Label, tone and icon for a request status; unknown statuses fall back to a neutral badge. */
export function statusMeta(status: string, fallbackLabel?: string): StatusMeta {
  const known = (STATUS_META as Record<string, StatusMeta | undefined>)[status]
  if (known) return known
  return { label: fallbackLabel || 'Unknown status', tone: 'grey', icon: 'clock' }
}

/** CSS class for a tone (palette defined in main.css, contrast >= 4.5:1 in both themes). */
export function toneClass(tone: Tone): string {
  return `tone tone-${tone}`
}

const OUTCOME_META: Readonly<Record<ResultOutcome, { label: string, tone: Tone, icon: IconName }>> = {
  submitted: { label: 'Submitted', tone: 'green', icon: 'check' },
  updated: { label: 'Updated', tone: 'green', icon: 'check' },
  cancelled: { label: 'Cancelled', tone: 'grey', icon: 'ban' },
  failed: { label: 'Submission failed', tone: 'red', icon: 'alert' },
}

export function outcomeMeta(outcome: string) {
  return (OUTCOME_META as Record<string, (typeof OUTCOME_META)[ResultOutcome] | undefined>)[outcome]
    ?? { label: 'Done', tone: 'grey' as Tone, icon: 'check' as IconName }
}

const CARD_STATE_META: Readonly<Record<Exclude<CardState, 'open'>, { label: string, tone: Tone, icon: IconName }>> = {
  used: { label: 'Confirmed', tone: 'green', icon: 'check' },
  superseded: { label: 'Replaced by a newer card', tone: 'grey', icon: 'ban' },
  discarded: { label: 'Discarded', tone: 'grey', icon: 'x' },
}

export function cardStateMeta(state: string) {
  return (CARD_STATE_META as Record<string, (typeof CARD_STATE_META)[keyof typeof CARD_STATE_META] | undefined>)[state]
    ?? { label: 'Closed', tone: 'grey' as Tone, icon: 'ban' as IconName }
}

/** Text of the loading state while a card action runs (the required "API loading state"). */
export function cardBusyLabel(action: CardAction, decision: 'confirm' | 'discard'): string {
  if (decision === 'discard') return 'Discarding...'
  return action === 'cancel' ? 'Cancelling request...' : 'Submitting to ReqRes...'
}

/* ---- Time ---- */

const MINUTE = 60_000
const HOUR = 60 * MINUTE
const DAY = 24 * HOUR

/** "just now", "5 min ago", "3 h ago", "yesterday", "4 d ago", then the ISO date. Bad input gives "". */
export function relativeTime(iso: string, now: number = Date.now()): string {
  const then = Date.parse(iso)
  if (Number.isNaN(then)) return ''
  const diff = now - then
  if (diff < MINUTE) return 'just now' // includes small clock skew into the future
  if (diff < HOUR) return `${Math.floor(diff / MINUTE)} min ago`
  if (diff < DAY) return `${Math.floor(diff / HOUR)} h ago`
  if (diff < 2 * DAY) return 'yesterday'
  if (diff < 7 * DAY) return `${Math.floor(diff / DAY)} d ago`
  return new Date(then).toISOString().slice(0, 10)
}

/** Clock time of a message, e.g. "11:05". `timeZone` is only passed by tests. */
export function formatClock(iso: string, timeZone?: string): string {
  const date = new Date(iso)
  if (Number.isNaN(date.getTime())) return ''
  return date.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit', hour12: false, timeZone })
}

/** Date and time for cards, e.g. "25 Sep 2026, 11:05". */
export function formatDateTime(iso: string | null | undefined, timeZone?: string): string {
  if (!iso) return ''
  const date = new Date(iso)
  if (Number.isNaN(date.getTime())) return ''
  return date.toLocaleString('en-GB', {
    day: 'numeric',
    month: 'short',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false,
    timeZone,
  })
}

/** "640 ms" or "1.2 s". */
export function formatDuration(ms: number): string {
  if (!Number.isFinite(ms) || ms < 0) return ''
  if (ms < 1000) return `${Math.round(ms)} ms`
  return `${(ms / 1000).toFixed(1)} s`
}

/* ---- Card fields ---- */

/** Value to show for a card field; blank values become an en dash. */
export function fieldValue(value: string | null | undefined): string {
  const text = (value ?? '').trim()
  return text || '–'
}

/** True when a field carries a real change (an old value that differs from the new one). */
export function fieldHasDiff(field: CardField): boolean {
  return field.old_value !== null && field.old_value !== undefined && field.old_value !== field.value
}

/* ---- Conversations ---- */

export function sortConversations(list: readonly ConversationSummary[]): ConversationSummary[] {
  return [...list].sort((a, b) => Date.parse(b.updated_at) - Date.parse(a.updated_at) || b.id - a.id)
}

/** Inserts or replaces a summary and keeps the list newest-first. */
export function upsertConversation(list: readonly ConversationSummary[], summary: ConversationSummary): ConversationSummary[] {
  return sortConversations([...list.filter(c => c.id !== summary.id), summary])
}

export interface ConversationBadge {
  kind: 'card' | 'form'
  label: string
}

/** Badges for the sidebar: an open card and/or the form type being filled. */
export function conversationBadges(summary: ConversationSummary): ConversationBadge[] {
  const badges: ConversationBadge[] = []
  if (summary.has_pending_card) badges.push({ kind: 'card', label: 'Awaiting confirmation' })
  if (summary.active_request_type) {
    badges.push({ kind: 'form', label: summary.active_request_type === 'leave' ? 'Leave form' : 'Claim form' })
  }
  return badges
}

/** A conversation the user has not typed into yet (safe to reuse instead of creating another). */
export function isEmptyConversation(summary: ConversationSummary | undefined, messages: readonly Message[]): boolean {
  return !!summary && messages.length === 0 && !summary.has_pending_card && !summary.active_request_type
}

/* ---- Messages ---- */

function byTime(a: Message, b: Message): number {
  return Date.parse(a.created_at) - Date.parse(b.created_at) || a.id - b.id
}

/** Merges messages by id (incoming wins) and orders them oldest-first. Optimistic (negative-id) messages stay last on ties. */
export function mergeMessages(existing: readonly Message[], incoming: readonly Message[]): Message[] {
  const byId = new Map<number, Message>()
  for (const message of [...existing, ...incoming]) byId.set(message.id, message)
  return [...byId.values()].sort(byTime)
}

/** Placeholder for the user's message while the request is in flight (negative id = not yet saved). */
export function optimisticMessage(tempId: number, content: string, now: Date = new Date(), attachments: AttachmentInfo[] = []): Message {
  return { id: tempId, sender_type: 'user', content, created_at: now.toISOString(), ui: null, trace: null, attachments }
}

export function isOptimistic(message: Message): boolean {
  return message.id < 0
}

/** Applies a TurnResponse: drops the optimistic message, merges the saved ones (user message first). */
export function applyTurn(messages: readonly Message[], tempId: number | null, turn: TurnResponse): Message[] {
  const kept = tempId === null ? messages : messages.filter(m => m.id !== tempId)
  const incoming = [...(turn.user_message ? [turn.user_message] : []), ...turn.assistant_messages]
  return mergeMessages(kept, incoming)
}

function isOpenCard(message: Message): boolean {
  return message.ui?.type === 'confirmation_card' && message.ui.state === 'open'
}

function withCardState(message: Message, state: CardState): Message {
  if (message.ui?.type !== 'confirmation_card') return message
  const ui: ConfirmationCardData = { ...message.ui, state }
  return { ...message, ui }
}

/**
 * Keeps card states consistent with the contract: only the newest confirmation card can be open, and no card
 * is open when the conversation has no pending card. `acted` records the decision the user just took.
 */
export function reconcileCards(
  messages: readonly Message[],
  opts: { hasPendingCard: boolean, acted?: { cardId: string, state: CardState } },
): Message[] {
  let next = messages.map(m =>
    opts.acted && m.ui?.type === 'confirmation_card' && m.ui.card_id === opts.acted.cardId
      ? withCardState(m, opts.acted.state)
      : m,
  )
  const openIndexes = next.flatMap((m, i) => (isOpenCard(m) ? [i] : []))
  const last = openIndexes[openIndexes.length - 1]
  next = next.map((m, i) => {
    if (!isOpenCard(m)) return m
    return i === last && opts.hasPendingCard ? m : withCardState(m, 'superseded')
  })
  return next
}

/** True when the newest message is one the user has not seen the answer to (used to decide auto-scroll). */
export function lastMessageIsUser(messages: readonly Message[]): boolean {
  return messages[messages.length - 1]?.sender_type === 'user'
}

/** Text spoken by the aria-live region for a new assistant message. */
export function announcementFor(message: Message): string {
  const parts = [message.content.trim()]
  if (message.ui?.type === 'confirmation_card' && message.ui.state === 'open') {
    parts.push(`${message.ui.title}. Use the ${message.ui.confirm_label} button or Discard.`)
  }
  else if (message.ui?.type === 'status_card') {
    parts.push(message.ui.requests.length ? `${message.ui.requests.length} request(s) listed.` : 'No matching requests.')
  }
  else if (message.ui?.type === 'result_card') {
    parts.push(message.ui.message)
  }
  return parts.filter(Boolean).join(' ')
}

/* ---- Composer ---- */

/** True when the trimmed text is 1..1000 characters (the backend counts the trimmed text) and no turn is in flight. */
export function canSend(text: string, busy: boolean): boolean {
  const length = text.trim().length
  return !busy && length > 0 && length <= MAX_MESSAGE_LENGTH
}

/** Characters left, counting the trimmed text like the backend does (negative = over the limit). */
export function remainingChars(text: string): number {
  return MAX_MESSAGE_LENGTH - text.trim().length
}

/** True when the scroll position is within `threshold` px of the bottom (so auto-scroll may follow new messages). */
export function isNearBottom(metrics: { scrollTop: number, scrollHeight: number, clientHeight: number }, threshold = 80): boolean {
  return metrics.scrollHeight - metrics.scrollTop - metrics.clientHeight <= threshold
}

/* ---- Errors ---- */

export type ChatAction = 'load' | 'send' | 'card'

/** User-facing message for a chat API failure (never echoes server text). `status` undefined = network error. */
export function chatErrorMessage(status: number | undefined, action: ChatAction): string {
  if (status === undefined) return 'Cannot reach the server. Check your connection and try again.'
  if (status === 403) return 'The chat is available to employees only.'
  if (status === 404) return 'That conversation could not be found.'
  if (status === 409) return 'That card is out of date.'
  if (status === 422) return action === 'send' ? 'That message could not be sent. Keep it between 1 and 1000 characters.' : 'That request was not accepted.'
  if (status === 429) return 'Too many requests. Please wait a moment and try again.'
  if (status >= 500) return 'The server had a problem. Please try again in a moment.'
  return 'Something went wrong. Please try again.'
}

const WARNING_MESSAGES: Readonly<Record<WarningCode, string>> = {
  llm_unavailable: 'The AI service is unavailable, please try again.',
  llm_invalid_output: 'The AI gave an answer I could not use. Please rephrase and try again.',
  submission_failed: 'The submission to ReqRes failed. Your request is saved; use Retry on the card to try again.',
  stale_card: 'That card is out of date.',
}

/** Banner text for a `warning_code`; null when there is nothing to show (or an unknown code). */
export function warningMessage(code: string | null | undefined): string | null {
  if (!code) return null
  return (WARNING_MESSAGES as Record<string, string | undefined>)[code] ?? 'Something needs your attention. Please try again.'
}
export interface ThemeConfig {
  lightPrimary: string
  lightSecondary: string
  lightBackground: string
  darkPrimary: string
  darkSecondary: string
  darkBackground: string
}

export type ThemeMode = 'light' | 'dark' | 'system'

export const DEFAULT_THEME: Readonly<ThemeConfig> = {
  lightPrimary: '#32a9e1',
  lightSecondary: '#1e40af',
  lightBackground: '#ffffff',
  darkPrimary: '#7dd3fc',
  darkSecondary: '#94a3b8',
  darkBackground: '#020617',
}

const HEX_RE = /^#(?:[0-9a-f]{3}|[0-9a-f]{6})$/i

export function isValidHex(value: unknown): value is string {
  return typeof value === 'string' && HEX_RE.test(value.trim())
}

/** Returns a lower-cased valid hex colour, or the fallback when malformed. */
export function sanitizeHex(value: unknown, fallback: string): string {
  return isValidHex(value) ? value.trim().toLowerCase() : fallback
}

export function resolveTheme(input?: Partial<Record<keyof ThemeConfig, unknown>> | null): ThemeConfig {
  const source = input ?? {}
  const out = { ...DEFAULT_THEME }
  for (const key of Object.keys(DEFAULT_THEME) as (keyof ThemeConfig)[]) {
    out[key] = sanitizeHex(source[key], DEFAULT_THEME[key])
  }
  return out
}

export function isThemeMode(value: unknown): value is ThemeMode {
  return value === 'light' || value === 'dark' || value === 'system'
}

/** Builds the :root CSS for light, prefers-color-scheme dark, and data-theme overrides. */
export function buildThemeCss(input?: Partial<Record<keyof ThemeConfig, unknown>> | null): string {
  const t = resolveTheme(input)
  // --theme-* feed the Tailwind @theme tokens (a token cannot reference its own name);
  // --color-* carry the same values for direct use.
  const vars = (p: string, s: string, b: string) =>
    `--theme-primary:${p};--theme-secondary:${s};--theme-background:${b};--color-primary:${p};--color-secondary:${s};--color-background:${b};`
  const light = vars(t.lightPrimary, t.lightSecondary, t.lightBackground)
  const dark = vars(t.darkPrimary, t.darkSecondary, t.darkBackground)
  return [
    `:root{${light}}`,
    `@media (prefers-color-scheme: dark){:root:not([data-theme="light"]){${dark}}}`,
    `:root[data-theme="light"]{${light}}`,
    `:root[data-theme="dark"]{${dark}}`,
  ].join('\n')
}

